<template><div class="space-y-6"><div class="page-header"><div><h1 class="page-title">Systeem & Beveiligingsinstellingen</h1><p class="page-subtitle">Beheer admin authenticatie en updates</p></div><span class="badge badge-purple">Amnion {{ stats?.version }}</span></div><div class="grid-2"><div class="glass-card"><h3 class="text-xl font-extrabold text-white mb-2">🔑 Wachtwoord Wijzigen</h3><p class="text-sm text-slate-400 mb-6">Wijzig het admin wachtwoord. Je wordt automatisch uitgelogd na wijziging.</p><form @submit.prevent="handleChangePassword" class="space-y-4"><div><label class="form-label">Huidig Wachtwoord</label><input type="password" v-model="pwdForm.oldPassword" required class="glass-input w-full" placeholder="Huidig wachtwoord" autocomplete="current-password"/></div><div><label class="form-label">Nieuw Wachtwoord (min. 8)</label><input type="password" v-model="pwdForm.newPassword" required minlength="8" class="glass-input w-full" placeholder="Nieuw wachtwoord" :class="{ 'border-red-500': passwordError }"/></div><div><label class="form-label">Bevestig Wachtwoord</label><input type="password" v-model="pwdForm.confirmPassword" required minlength="8" class="glass-input w-full" placeholder="Bevestig wachtwoord" :class="{ 'border-red-500': passwordError }"/></div><p v-if="passwordError" class="text-red-500 text-xs">{{ passwordError }}</p><button type="submit" :disabled="submitting" class="glass-btn glass-btn-primary w-full"><span v-if="submitting">Opslaan...</span><span v-else>Wachtwoord Opslaan & Uitloggen</span></button></form></div><div class="glass-card"><h3 class="text-xl font-extrabold text-white mb-2">🔐 REALITY Sleutels</h3><p class="text-sm text-slate-400 mb-6">Cryptografische sleutels voor VLESS REALITY.</p><div class="space-y-4"><div><label class="form-label">Public Key</label><div class="flex gap-2"><input type="text" readonly :value="realityDetails?.publicKey || 'Laden...'" class="glass-input flex-1 font-mono text-cyan-400"/><button @click="copyPublicKey" class="glass-btn glass-btn-secondary p-2" :data-tooltip="copiedPublicKey ? 'Gekopieerd!' : 'Kopieer'"><CopyIcon class="w-4 h-4"/></button></div></div><div><label class="form-label">Short ID</label><div class="flex gap-2"><input type="text" readonly :value="realityDetails?.shortId || 'Laden...'" class="glass-input flex-1 font-mono text-purple-400"/><button @click="copyShortId" class="glass-btn glass-btn-secondary p-2" :data-tooltip="copiedShortId ? 'Gekopieerd!' : 'Kopieer'"><CopyIcon class="w-4 h-4"/></button></div></div></div><div class="mt-6 p-4 bg-slate-800/50 rounded-xl border border-slate-700/50"><ShieldCheckIcon class="w-5 h-5 text-emerald-500 mt-0.5 float-left mr-3"/><p class="text-sm text-white font-medium mb-1">Privacy Garantie</p><p class="text-xs text-slate-400">SSL certificaten worden veilig opgeslagen in <code>/etc/amnion/env</code> met <code>0600</code> permissies.</p></div></div></div><div class="glass-card"><h3 class="text-xl font-extrabold text-white mb-2">🚀 Updates & Rollback</h3><p class="text-sm text-slate-400 mb-6">Controleer op updates of voer een rollback uit.</p><div class="flex items-center gap-4 flex-wrap"><button @click="handleCheckUpdates" :disabled="checkingUpdates" class="glass-btn glass-btn-secondary"><SearchIcon class="w-4 h-4"/><span>{{ checkingUpdates ? 'Controleren...' : 'Controleer Updates' }}</span></button><button @click="handleTriggerUpdate" :disabled="updating" class="glass-btn glass-btn-primary"><RefreshIcon class="w-4 h-4"/><span>{{ updating ? 'Update Bezig...' : 'Update Uitvoeren' }}</span></button><button @click="handleTriggerRollback" :disabled="rollingBack" class="glass-btn glass-btn-danger"><ArrowLeftIcon class="w-4 h-4"/><span>{{ rollingBack ? 'Rollback Bezig...' : 'Nood-Rollback' }}</span></button></div></div><UpdateProgressModal :isOpen="showUpdateModal" :step="updateProgress.step" :progressPercent="updateProgress.progressPercent" :message="updateProgress.message" :isFinished="updateProgress.progressPercent === 100" :isError="!!updateProgress.error" @close="showUpdateModal = false"/></div></template><script setup lang="ts">import { ref, onMounted, onUnmounted, watch } from 'vue';import { useRouter } from 'vue-router';import { useAuthStore } from '../stores/auth';import { useSystemStore } from '../stores/system';import { useToastStore } from '../stores/toast';import { useClipboard } from '../composables/useClipboard';import UpdateProgressModal from '../components/UpdateProgressModal.vue';import { KeyIcon, ShieldCheckIcon, CopyIcon, SearchIcon, RefreshIcon, ArrowLeftIcon } from '../components/Icons';const authStore = useAuthStore();const systemStore = useSystemStore();const toastStore = useToastStore();const router = useRouter();const pwdForm = ref({ oldPassword: '', newPassword: '', confirmPassword: '' });const stats = ref(systemStore.stats);const realityDetails = ref(systemStore.realityDetails);const updateProgress = ref(systemStore.updateProgress);const submitting = ref(false);const checkingUpdates = ref(false);const updating = ref(false);const rollingBack = ref(false);const showUpdateModal = ref(false);const passwordError = ref('');const { copied: copiedPublicKey, copyToClipboard: copyPublicKeyFn } = useClipboard();const { copied: copiedShortId, copyToClipboard: copyShortIdFn } = useClipboard();let pollTimer: any = null;onMounted(() => { systemStore.fetchStats(); systemStore.fetchRealityInfo(); });onUnmounted(() => { if (pollTimer) clearInterval(pollTimer); });watch(() => systemStore.stats, (val) => { stats.value = val; });watch(() => systemStore.realityDetails, (val) => { realityDetails.value = val; });watch(() => systemStore.updateProgress, (val) => { updateProgress.value = val; if (val.progressPercent === 100 || val.error) { if (pollTimer) clearInterval(pollTimer); } });function validatePassword() { if (pwdForm.value.newPassword !== pwdForm.value.confirmPassword) { passwordError.value = 'Wachtwoorden komen niet overeen.'; return false; } if (pwdForm.value.newPassword.length < 8) { passwordError.value = 'Wachtwoord moet minimaal 8 tekens zijn.'; return false; } passwordError.value = ''; return true; }async function handleChangePassword() { if (!validatePassword()) return; submitting.value = true; try { const res = await authStore.changePassword(pwdForm.value.oldPassword.trim(), pwdForm.value.newPassword.trim()); toastStore.addToast(res.message || 'Wachtwoord gewijzigd! Uitloggen...', 'success'); pwdForm.value = { oldPassword: '', newPassword: '', confirmPassword: '' }; setTimeout(async () => { await authStore.logout(); router.push({ name: 'login' }); }, 2000); } catch (err: any) { toastStore.addToast(err.response?.data?.error || 'Wachtwoord wijzigen mislukt.', 'error'); } finally { submitting.value = false; } }async function handleCheckUpdates() { checkingUpdates.value = true; try { const res = await systemStore.checkUpdates(); toastStore.addToast(res.message || 'Controle voltooid.', 'success'); } catch (err: any) { toastStore.addToast('Updates controleren mislukt.', 'error'); } finally { checkingUpdates.value = false; } }async function handleTriggerUpdate() { if (!confirm('Weet je zeker dat je een update wilt uitvoeren?')) return; updating.value = true; showUpdateModal.value = true; try { await systemStore.triggerUpdate(); pollTimer = setInterval(async () => { const status = await systemStore.fetchUpdateStatus(); if (status && (status.progressPercent === 100 || status.error)) { clearInterval(pollTimer); } }, 2000); } catch (err: any) { toastStore.addToast(err.response?.data?.error || 'Update starten mislukt.', 'error'); } finally { updating.value = false; } }async function handleTriggerRollback() { if (!confirm('Weet je zeker dat je een rollback wilt uitvoeren?')) return; rollingBack.value = true; try { const res = await systemStore.triggerRollback(); toastStore.addToast(res.message, 'success'); } catch (err: any) { toastStore.addToast(err.response?.data?.error || 'Rollback mislukt.', 'error'); } finally { rollingBack.value = false; } }function copyPublicKey() { if (realityDetails.value?.publicKey) { copyPublicKeyFn(realityDetails.value.publicKey); }}function copyShortId() { if (realityDetails.value?.shortId) { copyShortIdFn(realityDetails.value.shortId); }}</script>